// Final end-to-end workflow (the 16 demo steps), on a fresh database and a local Hardhat devnet
// (real transactions, chain id 31337; not a public network). Nothing is seeded from the old prototype:
// every passport version here is generated by the worker and registered on-chain.
//
// Steps 1, 2 and 6 use the closest equivalents that exist today and say so:
//   1-2: test-password sign-in with an allowed email domain (BTU Google sign-in is not built),
//   6:   a new row in a COPY of the Excel workbook (the Google Sheets reader is not built).
// Set EVIDENCE_DIR to keep the evidence (JSON log, PDFs, workbook copies, import reports).
// Run after `npm run build` and `cd chain && npm install`.
import { after, before, test } from "node:test";
import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import { createHash, randomBytes } from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import Database from "better-sqlite3";

const PORT = 3930;
const RPC_PORT = 8630;
const BASE = `http://127.0.0.1:${PORT}`;
const RPC = `http://127.0.0.1:${RPC_PORT}`;
const WORKBOOK = path.resolve(
  process.env.BTU_WORKBOOK ?? "samples/demo/workbook.xlsx",
);
const dataDir = fs.mkdtempSync(path.join(os.tmpdir(), "bdp-e2e-"));
const evidenceDir = process.env.EVIDENCE_DIR ? path.resolve(process.env.EVIDENCE_DIR) : null;
const key = () => "0x" + randomBytes(32).toString("hex"); // fresh keys, in memory only
const adminKey = key();
const issuerKey = key();
let env = { ...process.env, PASSPORT_PASSWORD_LOGIN: "1", DATA_DIR: dataDir, STUDENT_EMAIL_DOMAINS: "example.org" };
let server, node, registry, issuer;
const passwords = new Map();
const evidence = [];
const STUDENT = { email: "btu-t-0001@example.org", studentId: "BTU-T-0001", passportId: "BTU-AI-000125", firstIssued: "2026-09-15" };

const sha256 = (b) => createHash("sha256").update(b).digest("hex");
function run(cmd, args, extraEnv = {}) {
  const r = spawnSync(cmd, args, { env: { ...env, ...extraEnv }, encoding: "utf8" });
  assert.equal(r.status, 0, `${cmd} ${args.join(" ")}\n${r.stdout}\n${r.stderr}`);
  return r.stdout;
}
const rpc = async (method, params = []) =>
  (await (await fetch(RPC, { method: "POST", headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params }) })).json()).result;
const address = (k) =>
  run("python3", ["-c", "import sys; from eth_account import Account; print(Account.from_key(sys.argv[1]).address)", k]).trim();
const db = () => new Database(path.join(dataDir, "portal.db"), { readonly: true });
const record = (step, result, details) => {
  evidence.push({ step, result, ...details });
  if (evidenceDir) fs.writeFileSync(path.join(evidenceDir, "e2e-evidence.json"), JSON.stringify(evidence, null, 2));
};
const keep = (name, bytes) => evidenceDir && fs.writeFileSync(path.join(evidenceDir, name), bytes);
const lastReport = () => {
  const dir = path.join(dataDir, "reports");
  const f = fs.readdirSync(dir).sort((a, b) => Number(a.match(/\d+/)[0]) - Number(b.match(/\d+/)[0])).at(-1);
  return { name: f, body: JSON.parse(fs.readFileSync(path.join(dir, f), "utf8")) };
};
const versions = (passportId) =>
  db().prepare(`SELECT v.* FROM passport_versions v JOIN passports p ON p.id = v.passport_fk
                 WHERE p.passport_id = ? ORDER BY v.version_no`).all(passportId);
const clean = (html) => html.replaceAll("<!-- -->", "");

async function waitFor(url, init) {
  for (let i = 0; i < 160; i++) {
    try {
      return await fetch(url, init);
    } catch {
      await new Promise((r) => setTimeout(r, 250));
    }
  }
  throw new Error(`${url} did not start`);
}
async function login(email, password = passwords.get(email)) {
  return fetch(`${BASE}/api/auth/login`, { method: "POST", redirect: "manual", body: new URLSearchParams({ email, password }) });
}
const cookieOf = (res) => (res.headers.getSetCookie().find((c) => c.startsWith("bdp_session=")) ?? "").split(";")[0];
async function dashboard(cookie) {
  return clean(await (await fetch(`${BASE}/dashboard`, { headers: { cookie }, redirect: "manual" })).text());
}
async function verify(code, pdf) {
  const form = new FormData();
  form.set("code", code);
  if (pdf) form.set("pdf", new Blob([pdf], { type: "application/pdf" }), "passport.pdf");
  const res = await fetch(`${BASE}/api/verify`, { method: "POST", body: form }); // no cookie: public
  return { status: res.status, setCookie: res.headers.getSetCookie(), body: await res.json() };
}

before(async () => {
  if (evidenceDir) fs.mkdirSync(evidenceDir, { recursive: true });
  node = spawn(path.resolve("chain/node_modules/.bin/hardhat"), ["node", "--hostname", "127.0.0.1", "--port", String(RPC_PORT)], {
    cwd: path.resolve("chain"), stdio: "ignore",
  });
  await waitFor(RPC, { method: "POST", headers: { "content-type": "application/json" },
    body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "eth_chainId", params: [] }) });
  const admin = address(adminKey);
  issuer = address(issuerKey);
  for (const a of [admin, issuer]) await rpc("hardhat_setBalance", [a, "0x56BC75E2D63100000"]);
  registry = JSON.parse(run("python3", ["-m", "worker", "chain", "deploy", "--rpc", RPC], { PASSPORT_ADMIN_PRIVATE_KEY: adminKey })).registry;
  run("python3", ["-m", "worker", "chain", "set-issuer", "--rpc", RPC, "--registry", registry, "--issuer", issuer,
    "--label", "BTU hackathon TEST issuer"], { PASSPORT_ADMIN_PRIVATE_KEY: adminKey });
  const anchorPath = path.join(dataDir, "trust-anchor.json");
  run("python3", ["-m", "worker", "chain", "anchor", "--chain-id", "31337", "--network", "local Hardhat devnet",
    "--registry", registry, "--admin", admin, "--issuer", `${issuer}=BTU hackathon TEST issuer`, "--out", anchorPath]);
  env = { ...env, PASSPORT_CHAIN_RPC_URL: RPC, PASSPORT_CHAIN_ID: "31337", PASSPORT_CHAIN_NETWORK: "local Hardhat devnet",
    PASSPORT_REGISTRY_ADDRESS: registry, PASSPORT_CHAIN_CONFIRMATIONS: "1", PASSPORT_TRUST_ANCHOR: anchorPath,
    VERIFY_BASE_URL: `${BASE}/verify` };

  // First issuance from BTU's workbook: every student gets V1, registered on-chain.
  const out = run("python3", ["-m", "worker", "import", "--xlsx", WORKBOOK], { PASSPORT_ISSUER_PRIVATE_KEY: issuerKey });
  assert.match(out, /passports created 18, versions generated 18/);
  assert.match(out, /18 issued with blockchain registration/);
  for (const email of [STUDENT.email, "btu-t-0002@example.org"]) run("npx", ["tsx", "scripts/create-login.ts", email]);
  for (const line of fs.readFileSync(path.join(dataDir, "dev-credentials.txt"), "utf8").split("\n")) {
    const [email, password] = line.split("\t");
    if (email && password && !email.startsWith("#")) passwords.set(email, password);
  }
  server = spawn(process.execPath, ["node_modules/next/dist/bin/next", "start", "-p", String(PORT), "-H", "127.0.0.1"], { env, stdio: "ignore" });
  await waitFor(`${BASE}/login`);
  record("setup", "PASS", { note: "fresh database; registry deployed; TEST issuer authorised; 18 passports V1 issued and registered", registry, issuer });
});

after(() => {
  server?.kill();
  node?.kill();
  if (evidenceDir) {
    for (const d of ["reports", "exports"]) fs.cpSync(path.join(dataDir, d), path.join(evidenceDir, d), { recursive: true });
  }
  fs.rmSync(dataDir, { recursive: true, force: true });
});

let cookie, v1, v2, v1Pdf, v2Pdf;

test("steps 1-4: sign in (test password, BTU Google sign-in not built), other domains refused, own record, straight to the dashboard", async () => {
  const res = await login(STUDENT.email);
  assert.equal(res.status, 303);
  assert.equal(new URL(res.headers.get("location"), BASE).pathname, "/dashboard");
  cookie = cookieOf(res);
  assert.ok(cookie, "session cookie set");
  record(1, "BLOCKED", { equivalent: "PASS", note: "test-password sign-in for btu-t-0001@example.org succeeded; Google sign-in not built" });

  // an account outside the allowed domain is refused, even with a valid password for a real record
  const outsider = await login("outsider@gmail.com", "whatever-password");
  assert.match(outsider.headers.get("location"), /error=invalid/);
  assert.equal(cookieOf(outsider), "");
  const conn = new Database(path.join(dataDir, "portal.db"));
  conn.prepare("UPDATE students SET email = 'btu-t-0002@gmail.com' WHERE student_id = 'BTU-T-0002'").run();
  conn.close();
  const otherDomain = await login("btu-t-0002@gmail.com", passwords.get("btu-t-0002@example.org"));
  assert.match(otherDomain.headers.get("location"), /error=invalid/, "right password, wrong domain");
  assert.equal(cookieOf(otherDomain), "");
  const restore = new Database(path.join(dataDir, "portal.db"));
  restore.prepare("UPDATE students SET email = 'btu-t-0002@example.org' WHERE student_id = 'BTU-T-0002'").run();
  restore.close();
  record(2, "BLOCKED", { equivalent: "PASS", note: "emails outside STUDENT_EMAIL_DOMAINS are refused even with a correct password; Google hosted-domain check not built" });

  const html = await dashboard(cookie);
  assert.ok(html.includes(`data-testid="passport-id">${STUDENT.passportId}<`));
  assert.ok(!html.includes("BTU-AI-000126"), "no other student's passport");
  record(3, "PASS", { note: `${STUDENT.email} → Student ID ${STUDENT.studentId} → Passport ${STUDENT.passportId}` });
  record(4, "PASS", { note: "login answers 303 → /dashboard" });
});

test("step 5: the existing multi-page PDF appears and downloads", async () => {
  [v1] = versions(STUDENT.passportId);
  assert.equal(v1.status, "CURRENT");
  const html = await dashboard(cookie);
  assert.ok(html.includes('data-testid="pdf-viewer"'));
  assert.ok(html.includes(`data-testid="verification-code">${v1.verification_code}<`));
  const res = await fetch(`${BASE}/api/passport/pdf?download=1`, { headers: { cookie } });
  assert.equal(res.status, 200);
  assert.match(res.headers.get("content-disposition"), /attachment; filename="BTU-AI-000125_V1.pdf"/);
  v1Pdf = Buffer.from(await res.arrayBuffer());
  assert.equal(sha256(v1Pdf), v1.pdf_sha256);
  const pages = Number(run("python3", ["-c", "import sys,fitz; print(fitz.open(sys.argv[1]).page_count)", path.join(dataDir, "storage", v1.pdf_storage_key)]).trim());
  assert.ok(pages >= 4, `multi-page (${pages})`);
  keep("V1.pdf", v1Pdf);
  record(5, "PASS", { pages, sha256: v1.pdf_sha256, code: v1.verification_code });
});

test("steps 6-12: a new CONFIRMED skill in the source sheet becomes V2, registered on-chain, then current", async () => {
  // 6. the workbook copy gets a Verification Status column and four new rows
  const edited = path.join(dataDir, "with-new-skill.xlsx");
  const added = JSON.parse(run("python3", ["tests/fixtures/confirmed_rows.py", WORKBOOK, edited]));
  if (evidenceDir) fs.copyFileSync(edited, path.join(evidenceDir, "workbook-with-new-skill.xlsx"));
  record(6, "BLOCKED", { equivalent: "PASS", note: "row added to a COPY of the Excel workbook (Google Sheets reader not built)", added });

  // 7 + 11. without the issuer key the new version is generated but waits; V1 stays current
  const blocksBefore = Number(await rpc("eth_blockNumber"));
  let out = run("python3", ["-m", "worker", "import", "--xlsx", edited]);
  assert.match(out, /awards: 1 new/);
  assert.match(out, /versions generated 1/);
  assert.match(out, /1 waiting for registration/);
  const report = lastReport().body;
  const has = (rec, code) => report.issues.some((i) => i.record_id === rec && i.code === code);
  assert.ok(has("REC-0902", "NOT_CONFIRMED"), "PENDING row held");
  assert.ok(has("REC-0903", "NOT_CONFIRMED"), "REJECTED row held");
  assert.ok(report.issues.some((i) => i.record_id === "REC-0904" && i.severity === "ERROR"), "invalid Student ID is an error");
  assert.ok(report.issues.some((i) => i.record_id === "REC-0905" && i.severity === "ERROR"), "unknown Student ID claiming another passport is an error");
  for (const pid of ["BTU-AI-000126", "BTU-AI-000127"]) assert.equal(versions(pid).length, 1, `${pid} unchanged`);
  assert.equal(versions(STUDENT.passportId).length, 1, "V2 not issued yet");
  assert.match(await dashboard(cookie), /data-testid="awaiting-registration"/);
  assert.equal(Number(await rpc("eth_blockNumber")), blocksBefore, "nothing sent to the chain without the issuer key");
  record(7, "PASS", { note: "REC-0901 (CONFIRMED) accepted for BTU-T-0001 only; PENDING/REJECTED held; bad Student IDs rejected", issues: report.issues.filter((i) => i.code !== "BADGE_FROM_FORMULA") });

  // 10. with the issuer key the waiting version is registered, confirmed and read back, then issued
  out = run("python3", ["-m", "worker", "import", "--xlsx", edited], { PASSPORT_ISSUER_PRIVATE_KEY: issuerKey });
  assert.match(out, /1 issued with blockchain registration/);
  [v1, v2] = versions(STUDENT.passportId);
  assert.equal(v1.status, "SUPERSEDED");
  assert.equal(v2.status, "CURRENT");
  record(11, "PASS", { note: "V2 waited (V1 current) until registration succeeded; then V2 CURRENT, V1 SUPERSEDED" });

  // 8. same Passport ID and first-issue date, inside the PDF too
  const p = db().prepare("SELECT * FROM passports WHERE passport_id = ?").get(STUDENT.passportId);
  assert.equal(p.first_issued_on, STUDENT.firstIssued);
  const text = run("python3", ["-c", "import sys,fitz; d=fitz.open(sys.argv[1]); print(d.page_count); print(d[0].get_text())",
    path.join(dataDir, "storage", v2.pdf_storage_key)]);
  assert.ok(text.includes(STUDENT.passportId) && text.includes("15.09.2026"), "cover keeps Passport ID and first issue date");
  assert.ok(text.includes("V2") && text.includes(v2.verification_code));
  assert.notEqual(v2.verification_code, v1.verification_code);
  record(8, "PASS", { passportId: p.passport_id, firstIssued: p.first_issued_on, v1Code: v1.verification_code, v2Code: v2.verification_code });

  // 9. SHA-256 of the exact stored bytes = recorded hash = on-chain hash
  const stored = fs.readFileSync(path.join(dataDir, "storage", v2.pdf_storage_key));
  assert.equal(sha256(stored), v2.pdf_sha256);
  record(9, "PASS", { sha256: v2.pdf_sha256 });

  // 10. the transaction exists, succeeded, and was sent by the authorised issuer
  const tx = await rpc("eth_getTransactionByHash", [v2.chain_tx_hash]);
  const receipt = await rpc("eth_getTransactionReceipt", [v2.chain_tx_hash]);
  assert.equal(receipt.status, "0x1");
  assert.equal(tx.from.toLowerCase(), issuer.toLowerCase());
  assert.equal(tx.to.toLowerCase(), registry.toLowerCase());
  assert.ok(tx.input.includes(v2.pdf_sha256), "the PDF hash is in the transaction input");
  record(10, "PASS", { txHash: v2.chain_tx_hash, block: Number(receipt.blockNumber), from: tx.from, registry, issuerLabel: v2.chain_issuer_label ?? "BTU hackathon TEST issuer",
    note: "issuer is a TEST issuer authorised by the registry admin and named in a TEST trust anchor; no BTU authorisation" });

  // 12. the next dashboard visit shows V2, V1 in history
  const html = await dashboard(cookie);
  assert.ok(html.includes(`data-testid="verification-code">${v2.verification_code}<`));
  assert.match(html, /data-testid="history"/);
  assert.ok(html.includes("V1") && html.includes("V2"));
  assert.ok(html.includes('data-claim="integrity" data-state="ok"') && html.includes('data-claim="official" data-state="pending"'),
    "the document is shown as unchanged since issue, and official BTU issuance as pending (TEST issuer)");
  const dl = await fetch(`${BASE}/api/passport/pdf?download=1`, { headers: { cookie } });
  v2Pdf = Buffer.from(await dl.arrayBuffer());
  assert.equal(sha256(v2Pdf), v2.pdf_sha256);
  keep("V2.pdf", v2Pdf);
  record(12, "PASS", { note: "dashboard shows V2 as current with V1 in history; download is V2" });
});

test("step 13: the exact PDF passes public verification without login", async () => {
  const r = await verify(v2.verification_code, v2Pdf);
  assert.equal(r.status, 200);
  assert.equal(r.setCookie.length, 0);
  assert.deepEqual([r.body.record, r.body.chain, r.body.file, r.body.version], ["FOUND", "CONFIRMED", "MATCH", "CURRENT"]);
  assert.equal(r.body.issuer, "TEST_ISSUER");
  assert.equal(r.body.evidence.txHash, v2.chain_tx_hash);
  for (const personal of ["Giorgi", "Kapanadze", "example.org", "BTU-T-0001"]) assert.ok(!JSON.stringify(r.body).includes(personal));
  const page = await fetch(`${BASE}/verify/${v2.verification_code}`);
  assert.equal(page.status, 200);
  record(13, "PASS", { checks: { record: r.body.record, chain: r.body.chain, file: r.body.file, version: r.body.version, issuer: r.body.issuer }, overall: r.body.overall,
    note: "document checks pass; issuer is a TEST issuer, so it is never called an official BTU issuance" });
});

test("step 14: a modified PDF fails the integrity check", async () => {
  // a real content edit: the student's name on the cover is overwritten, then saved as a new PDF
  const edited = path.join(dataDir, "edited.pdf");
  fs.writeFileSync(path.join(dataDir, "v2.pdf"), v2Pdf);
  run("python3", ["-c", `import sys,fitz
d=fitz.open(sys.argv[1]); p=d[0]
p.insert_text((60,120),"AI Data Analysis - Expert",fontsize=12)
d.save(sys.argv[2])`, path.join(dataDir, "v2.pdf"), edited]);
  const bytes = fs.readFileSync(edited);
  keep("V2-modified.pdf", bytes);
  const r = await verify(v2.verification_code, bytes);
  assert.deepEqual([r.body.record, r.body.file, r.body.overall], ["FOUND", "MISMATCH", "NOT_VERIFIED"]);
  const oneByte = Buffer.from(v2Pdf);
  oneByte[Math.floor(oneByte.length / 2)] ^= 1;
  assert.equal((await verify(v2.verification_code, oneByte)).body.file, "MISMATCH");
  const unknown = await verify("BTU-0000-0000-0000", v2Pdf);
  assert.deepEqual([unknown.body.record, unknown.body.overall], ["NOT_FOUND", "NOT_VERIFIED"]);
  record(14, "PASS", { modifiedSha256: sha256(bytes), note: "edited cover text and a one-byte flip both give MISMATCH / NOT_VERIFIED; unknown code gives NOT_FOUND" });
});

test("step 15: the previous version is authentic as a historical version and marked superseded", async () => {
  const r = await verify(v1.verification_code, v1Pdf);
  assert.deepEqual([r.body.record, r.body.chain, r.body.file, r.body.version], ["FOUND", "CONFIRMED", "MATCH", "SUPERSEDED"]);
  assert.notEqual(r.body.overall, "AUTHENTIC_CURRENT");
  const mixed = await verify(v2.verification_code, v1Pdf);
  assert.equal(mixed.body.file, "MISMATCH", "V1's file does not pass as V2");
  record(15, "PASS", { checks: { record: r.body.record, file: r.body.file, version: r.body.version, issuer: r.body.issuer } });
});

test("step 16: re-running synchronization changes nothing", async () => {
  const edited = path.join(dataDir, "with-new-skill.xlsx");
  const blocks = Number(await rpc("eth_blockNumber"));
  const counts = () => db().prepare(`SELECT (SELECT COUNT(*) FROM skill_awards) a, (SELECT COUNT(*) FROM passport_versions) v,
                                            (SELECT COUNT(*) FROM version_candidates) c`).get();
  const before = counts();
  for (let i = 0; i < 2; i++) {
    const out = run("python3", ["-m", "worker", "import", "--xlsx", edited], { PASSPORT_ISSUER_PRIVATE_KEY: issuerKey });
    assert.match(out, /awards: 0 new/);
    assert.match(out, /versions generated 0/);
  }
  assert.deepEqual(counts(), before);
  assert.equal(Number(await rpc("eth_blockNumber")), blocks, "no new transactions");
  record(16, "PASS", { before, after: counts(), note: "two more runs: 0 new awards, 0 versions, 0 transactions" });
});

test("extra: on the local devnet the transaction links open the portal's page, read live from the chain", async () => {
  const dash = await dashboard(cookie);
  const href = dash.match(/href="(\/chain\/tx\/0x[0-9a-f]{64})"/)?.[1];
  assert.ok(href, "the dashboard links the transaction to the local page");
  assert.equal(href, `/chain/tx/${v2.chain_tx_hash}`);
  const page = clean(await (await fetch(`${BASE}${href}`)).text());
  assert.ok(page.includes('data-testid="local-tx"') && page.includes(">success<"));
  assert.ok(page.includes(v2.pdf_sha256.toLowerCase()) && page.includes('data-testid="local-tx-match"'), "on-chain hash matches the stored PDF");
  assert.ok(page.includes(STUDENT.passportId) && !page.includes(STUDENT.email), "Passport ID only, no email");
  const unknown = clean(await (await fetch(`${BASE}/chain/tx/0x${"ab".repeat(32)}`)).text());
  assert.ok(unknown.includes('data-testid="local-tx-error"'));
  assert.equal((await fetch(`${BASE}/chain/tx/not-a-hash`)).status, 404);
});
